def __repr__(self):
        cn = self.__class__.__name__
        parts = []
        if self.spec is not T:
            parts.append(repr(self.spec))
        if self.types:
            if len(self.types) == 1:
                parts.append('type=%s' % (self.types[0].__name__,))
            else:
                parts.append('type=%s' % (tuple(t.__name__ for t in self.types),))
        if self.instance_of:
            if len(self.instance_of) == 1:
                parts.append('instance_of=%s' % (self.instance_of[0].__name__,))
            else:
                parts.append('instance_of=%s' % (tuple(t.__name__ for t in self.instance_of),))
        if self.validators:
            # Check if these are the default truthy validators
            is_default = len(self.validators) == 1 and self.validators[0].func is bool
            if not is_default:
                parts.append('validate=%r' % (self.validators,))
        if getattr(self, 'vals', None):
            if len(self.vals) == 1:
                parts.append('equal_to=%r' % (self.vals[0],))
            else:
                parts.append('one_of=%r' % (self.vals,))
        if self.default is not RAISE:
            parts.append('default=%r' % (self.default,))
        if not parts:
            return '%s()' % (cn,)
        return '%s(%s)' % (cn, ', '.join(parts))
